const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([142.41, -32.38]).buffer(15000);
  const startDate = ee.Date('2017-01-27');
  const endDate = ee.Date('2019-02-02');

  // Helper function to calculate water area
  const getWaterArea = (date, collectionName) => {
    const dateRange = date.advance(-15, 'day').getRange(date.advance(15, 'day'));
    let imageCollection = ee.ImageCollection(collectionName)
      .filterBounds(aoi)
      .filterDate(dateRange);

    // If Sentinel-2 is empty, try Landsat 8 as a fallback.
    if (imageCollection.size().getInfo() === 0 && collectionName === 'COPERNICUS/S2_SR') {
        console.log(`No Sentinel-2 images found for ${date.format('YYYY-MM-dd').getInfo()}, trying Landsat 8.`);
        return getWaterArea(date, 'LANDSAT/LC08/C02/T1_L2');
    }

    if (imageCollection.size().getInfo() === 0) {
        return { 'image_count': 0 };
    }

    // Cloud masking and MNDWI calculation logic
    const calculateMNDWI = (image) => {
      let mndwi;
      if (collectionName.includes('S2')) { // Sentinel-2
        mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI'); // Green, SWIR1
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return mndwi.updateMask(mask);
      } else { // Landsat 8
        mndwi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI'); // Green, SWIR1
        const qa = image.select('QA_PIXEL');
        const cloudMask = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4)); // Cloud, Cloud Shadow
        return mndwi.updateMask(cloudMask.not());
      }
    };

    const mndwiCollection = imageCollection.map(calculateMNDWI);
    const medianMNDWI = mndwiCollection.median();
    const waterMask = medianMNDWI.select('MNDWI').gt(0.0);

    // Calculate the area of water
    const waterArea = waterMask.multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 100, // Finer scale for more accurate area
      maxPixels: 1e10
    });

    const pixelCount = waterMask.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 100,
        maxPixels: 1e10
    });

    return {
      'area': waterArea.get('MNDWI'),
      'pixel_count': pixelCount.get('MNDWI'),
      'image_count': imageCollection.size()
    };
  };

  // 2. Data Acquisition & Processing
  const data2017 = getWaterArea(startDate, 'COPERNICUS/S2_SR');
  const data2019 = getWaterArea(endDate, 'COPERNICUS/S2_SR');

  const count2017 = data2017.image_count.getInfo();
  const count2019 = data2019.image_count.getInfo();

  if (count2017 === 0 || count2019 === 0) {
    console.log(`Image count 2017: ${count2017}`);
    console.log(`Image count 2019: ${count2019}`);
    console.log("Empty collection for one or both dates.");
    console.log("A"); // C1
    return;
  }

  const area2017 = ee.Number(data2017.area).getInfo();
  const area2019 = ee.Number(data2019.area).getInfo();
  const pixels2017 = ee.Number(data2017.pixel_count).getInfo();
  const pixels2019 = ee.Number(data2019.pixel_count).getInfo();

  if (area2017 === null || area2019 === null) {
      console.log(`2017 Area: ${area2017}, 2019 Area: ${area2019}`);
      console.log("Calculation failed, result is null.");
      console.log("A"); // C3
      return;
  }

  if (pixels2017 === 0 || pixels2019 === 0) {
      console.log(`Valid pixels 2017: ${pixels2017}`);
      console.log(`Valid pixels 2019: ${pixels2019}`);
      console.log("No valid pixels after cloud masking.");
      console.log("A"); // C2
      return;
  }

  // Convert area from square meters to square kilometers
  const areaKm2_2017 = area2017 / 1e6;
  const areaKm2_2019 = area2019 / 1e6;

  // 3. Validation & Final Answer
  console.log(`Lake Menindee Water Area (Jan 2017): ${areaKm2_2017.toFixed(2)} km^2`);
  console.log(`Lake Menindee Water Area (Feb 2019): ${areaKm2_2019.toFixed(2)} km^2`);

  if (areaKm2_2019 < areaKm2_2017) {
    console.log("Evidence: The water area in 2019 is less than in 2017.");
    console.log("A");
  } else {
    console.log("Evidence: The water area in 2019 is not less than in 2017.");
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
